        {"code": '396', "name": 'Deterioro de valor de los subproductos, residuos y materiales recuperados GRUPO 4 ACREEDORES Y DEUDORES POR OPERACIONES COMERCIALES', "description": None, "is_postable": True, "parent_code": '39'},
