        {"code": '71', "name": 'VARIACIÓN DE EXISTENCIAS', "description": None, "is_postable": False, "parent_code": '7'},
        {"code": '710', "name": 'Variación de existencias de productos en cur so', "description": None, "is_postable": True, "parent_code": '71'},
        {"code": '711', "name": 'Variación de existencias de productos semi terminados', "description": None, "is_postable": True, "parent_code": '71'},
