        {"code": '76210', "name": 'Ingresos de créditos a corto plazo, empresas del grupo', "description": None, "is_postable": True, "parent_code": '7621'},
        {"code": '76211', "name": 'Ingresos de créditos a corto plazo, empresas asociadas', "description": None, "is_postable": True, "parent_code": '7621'},
