        {"code": '773', "name": 'Beneficios procedentes de participaciones a largo plazo en partes vinculadas', "description": None, "is_postable": False, "parent_code": '77'},
        {"code": '7733', "name": 'Beneficios procedentes de participaciones a largo plazo, empresas del grupo', "description": None, "is_postable": True, "parent_code": '773'},
        {"code": '7734', "name": 'Beneficios procedentes de participaciones a largo plazo, empresas asociadas', "description": None, "is_postable": True, "parent_code": '773'},
        {"code": '7735', "name": 'Beneficios procedentes de participaciones a largo plazo, otras partes vinculadas', "description": None, "is_postable": True, "parent_code": '773'},
        {"code": '774', "name": 'Diferencia negativa en combinaciones de negocios', "description": 'Es el exceso, en la fecha de adquisición, del valor razonable de los activos identificables adquiridos menos el de los pasivos asumidos, sobre el coste de la combinación de negocios. Se abonará, por dicho importe con cargo a las correspondientes cuentas de los grupos 2, 3, 4 y 5.', "is_postable": True, "parent_code": '77'},
        {"code": '775', "name": 'Beneficios por operaciones con obligaciones propias', "description": 'Beneficios producidos con motivo de la amortización de obligaciones. Se abonará, por los beneficios producidos al amortizar los valores con car- go a cuentas del subgrupo 17.', "is_postable": True, "parent_code": '77'},
        {"code": '778', "name": 'Ingresos excepcionales', "description": '770/771/772. Beneficios procedentes del inmovilizado... Beneficios producidos en la enajenación de inmovilizado intangible, material o las inversiones inmobiliarias. Se abonarán por el beneficio obtenido en la enajenación con cargo, general- mente, a las cuentas del grupo 5 que correspondan.', "is_postable": True, "parent_code": '77'},
        {"code": '79', "name": 'EXCESOS Y APLICACIONES DE PROVISIONES Y DE PÉRDIDAS POR DETERIORO', "description": 'DETERIORO', "is_postable": False, "parent_code": '7'},
        {"code": '790', "name": 'Reversión del deterioro del inmovilizado intangible', "description": None, "is_postable": True, "parent_code": '79'},
        {"code": '791', "name": 'Reversión del deterioro del inmovilizado material', "description": None, "is_postable": True, "parent_code": '79'},
        {"code": '792', "name": 'Reversión del deterioro de las inversiones inmobiliarias', "description": None, "is_postable": True, "parent_code": '79'},
        {"code": '793', "name": 'Reversión del deterioro de existencias', "description": 'Importe de la corrección por deterioro existente al cierre del ejercicio anterior. Se abonará, al cierre del ejercicio, por el deterioro contabilizado en el ejer- cicio precedente, con cargo a cuentas del subgrupo 39 o a la cuenta 599.', "is_postable": False, "parent_code": '79'},
        {"code": '7930', "name": 'Reversión del deterioro de productos terminados y en curso de fabricación', "description": None, "is_postable": True, "parent_code": '793'},
        {"code": '7931', "name": 'Reversión del deterioro de mercaderías', "description": None, "is_postable": True, "parent_code": '793'},
        {"code": '7932', "name": 'Reversión del deterioro de materias primas', "description": None, "is_postable": True, "parent_code": '793'},
        {"code": '7933', "name": 'Reversión del deterioro de otros aprovisionamientos', "description": None, "is_postable": True, "parent_code": '793'},
        {"code": '794', "name": 'Reversión del deterioro de créditos por operaciones comerciales', "description": 'Importe de la corrección por deterioro existente al cierre del ejercicio anterior. Se abonará por el deterioro contabilizado en el ejer cicio precedente, con cargo a las cuentas 490, 493 ó 599. Cuando se utilice la alternativa segunda previs ta en la cuenta 490, la defini- ción y movimiento contable se adaptarán a lo establecido en dicha cuenta.', "is_postable": True, "parent_code": '79'},
        {"code": '795', "name": 'Exceso de provisiones', "description": '7950/7951/7952/7954/7955/7956/7957 Diferencia positiva entre el importe de la provisión existente y el que co- rresponda al cierre del ejercicio o en el momento de atender la correspondien- te obligación. Las cuentas citadas de cuatro cifras se abonarán, por el exceso de provisión con cargo a las correspondientes cuentas del subgrupo 14 o a las cuentas 499 ó 529.', "is_postable": False, "parent_code": '79'},
        {"code": '7950', "name": 'Exceso de provisión por retribuciones al personal', "description": None, "is_postable": True, "parent_code": '795'},
        {"code": '7951', "name": 'Exceso de provisión para impuestos', "description": None, "is_postable": True, "parent_code": '795'},
        {"code": '7952', "name": 'Exceso de provisión para otras responsabilidades', "description": None, "is_postable": True, "parent_code": '795'},
