        {"code": '797', "name": 'Reversión del deterioro de créditos a largo plazo', "description": 'Corrección valorativa, por la recuperación de valor en créditos de los subgrupos 24 y 25 o, en su caso, del subgrupo 58. Se abonará por el importe de la corrección de valor, con cargo a las cuentas 295, 298 ó 599.', "is_postable": False, "parent_code": '79'},
