def populate_pgc(apps, schema_editor):
    TemplateAccount = apps.get_model("accounting", "TemplateAccount")
    CompanyAccount = apps.get_model("accounting", "CompanyAccount")

    # Both CompanyAccount and TemplateAccount have self-referential parent FKs
    # with PROTECT. We must null out parent references on both before deleting,
    # otherwise Django refuses to delete any row that is still someone's parent.
    CompanyAccount.objects.all().update(parent=None)
    CompanyAccount.objects.all().delete()
    TemplateAccount.objects.filter(template_id=TEMPLATE_ID).update(parent=None)
    TemplateAccount.objects.filter(template_id=TEMPLATE_ID).delete()

    code_to_id = {}

    # Pass 1: insert all accounts, parent=None for now
    for acc in ACCOUNTS:
        obj = TemplateAccount.objects.create(
            template_id=TEMPLATE_ID,
            code=acc["code"],
            name=acc["name"],
            is_postable=acc["is_postable"],
            #description=acc["description"],  
        )
        code_to_id[acc["code"]] = obj.pk

    # Pass 2: wire up parent_id now that all rows exist
    for acc in ACCOUNTS:
        if acc["parent_code"] is not None:
            parent_pk = code_to_id.get(acc["parent_code"])
            if parent_pk:
                TemplateAccount.objects.filter(
                    pk=code_to_id[acc["code"]]
                ).update(parent_id=parent_pk)


